use zopro_bn254::{FpConfig,FqConfig,FrConfig,ifma8::Ifma8};
#[inline(always)]fn operation<C:FpConfig,const M:usize,const NEW:bool>(a:&[Ifma8<C,true>;6])->Ifma8<C,true>{if NEW{match M{0=>a[0].affine_mul_minus(&a[1],&a[4]),1=>a[0].affine_mul_minus_sum(&a[1],&a[4],&a[5]),2=>a[0].affine_mul_double_minus_sum(&a[1],&a[4],&a[5]),3=>a[0].affine_sum2_minus(&a[1],&a[2],&a[3],&a[4]),4=>a[0].affine_difference2_minus(&a[1],&a[2],&a[3],&a[4]),_=>unreachable!()}}else{match M{0=>a[0].mul(&a[1]).sub(&a[4]),1=>a[0].mul(&a[1]).sub(&a[4].add_canonical(&a[5])),2=>{let p=a[0].mul(&a[1]);p.add(&p).sub(&a[4].add_canonical(&a[5]))},3=>a[0].sum2(&a[1],&a[2],&a[3]).sub(&a[4]),4=>a[0].difference2(&a[1],&a[2],&a[3]).sub(&a[4]),_=>unreachable!()}}}
macro_rules! wrappers{($old:ident,$new:ident,$c:ty,$m:literal)=>{#[no_mangle]#[inline(never)]pub fn $old(a:&[Ifma8<$c,true>;6])->Ifma8<$c,true>{operation::<$c,$m,false>(a)}#[no_mangle]#[inline(never)]pub fn $new(a:&[Ifma8<$c,true>;6])->Ifma8<$c,true>{operation::<$c,$m,true>(a)}}}
wrappers!(cg_old_fq_0,cg_new_fq_0,FqConfig,0);wrappers!(cg_old_fq_1,cg_new_fq_1,FqConfig,1);wrappers!(cg_old_fq_2,cg_new_fq_2,FqConfig,2);wrappers!(cg_old_fq_3,cg_new_fq_3,FqConfig,3);wrappers!(cg_old_fq_4,cg_new_fq_4,FqConfig,4);
wrappers!(cg_old_fr_0,cg_new_fr_0,FrConfig,0);wrappers!(cg_old_fr_1,cg_new_fr_1,FrConfig,1);wrappers!(cg_old_fr_2,cg_new_fr_2,FrConfig,2);wrappers!(cg_old_fr_3,cg_new_fr_3,FrConfig,3);wrappers!(cg_old_fr_4,cg_new_fr_4,FrConfig,4);
fn check<C:FpConfig>(functions:[[fn(&[Ifma8<C,true>;6])->Ifma8<C,true>;2];5])->u64{let a:[Ifma8<C,true>;6]=std::array::from_fn(|j|unsafe{Ifma8::affine_offset_from_raw(&std::array::from_fn(|i|[(17+j*73+i*31)as u64,0,0,0]))});let a=std::hint::black_box(a);let functions=std::hint::black_box(functions);let mut sum=0;for pair in functions{let old=pair[0](&a).get();let new=pair[1](&a).get();assert_eq!(old,new);sum^=new[0].0[0];}sum}
fn main(){let q=check::<FqConfig>([[cg_old_fq_0,cg_new_fq_0],[cg_old_fq_1,cg_new_fq_1],[cg_old_fq_2,cg_new_fq_2],[cg_old_fq_3,cg_new_fq_3],[cg_old_fq_4,cg_new_fq_4]]);let r=check::<FrConfig>([[cg_old_fr_0,cg_new_fr_0],[cg_old_fr_1,cg_new_fr_1],[cg_old_fr_2,cg_new_fr_2],[cg_old_fr_3,cg_new_fr_3],[cg_old_fr_4,cg_new_fr_4]]);println!("All20 actual codegen wrappers retained and output checked; checksum={}",q^r);}
